function externalAccess({source,query='',publication='',cpc='',from=2021,to=2025}={}){
 if(typeof query!=='string'||query.length>1000)throw new Error('Invalid public search query');
 if(source==='patentbots')return {source,mode:'interactive-reference',url:'https://www.patentbots.com/stats/',searchFor:query,authority:'secondary-derived-examiner-analytics',access:'Basic statistics require a free login; premium detail requires a subscription.',automaticPolling:false,reason:'Published terms prohibit systematic downloading and scraping. Use an authorized provider integration if one is agreed.',terms:'https://www.patentbots.com/terms',warning:'Grant rates, difficulty and predictions are vendor calculations, not USPTO findings.'};
 if(source==='freepatentsonline')return {source,mode:'hosted-search-link',url:'https://www.freepatentsonline.com/Search/SearchBox.html?query_txt='+encodeURIComponent(query),searchFor:query,retrieved:false,authority:'third-party-reproduction-and-metadata',access:'Website search and free account features are available. The provider separately advertises commercial API and custom data services.',automaticPolling:false,reason:'No public free API entitlement or automated polling permission has been verified.',fields:'Website search supports patent text, dates, assignees, inventors, examiner names and classifications.',warning:'Search results and vendor metadata are leads. Verify patent text and legal status against the issuing authority or the original document.',docs:'https://www.freepatentsonline.com/search.html'};
 if(source==='wipo-patentscope')return {source,mode:'manual-search-access',url:'https://patentscope.wipo.int/search/en/search.jsf',searchFor:query,retrieved:false,connected:false,authority:'official-wipo-search',access:'Free manual website search. A free WIPO account permits result-list downloads of up to 10,000 records and adds saved-search features.',automaticPolling:false,reason:'WIPO prohibits robots and bulk download from PATENTSCOPE, and no free search API is configured. Run the query manually and treat any export as a separately acquired source.',coverage:'Published PCT applications and participating national and regional collections. Collection coverage and update timing differ.',countingWarning:'PATENTSCOPE groups an application, its successive publications, and the potential patent as one document; result counts are not patent-family, ownership, or legal-status conclusions.',docs:'https://www.wipo.int/en/web/patentscope/faqs_patentscope',userGuide:'https://www.wipo.int/documents/d/patentscope/docs-en-patentscope_user_guide.pdf'};
 if(source==='wipo-ip-statistics')return {source,mode:'manual-data-access',url:'https://www3.wipo.int/ipstats/',searchFor:query,retrieved:false,connected:false,authority:'official-wipo-statistics',access:'Free interactive service. Select indicators in the Data Center, then view or download the resulting latest or historical aggregate data.',automaticPolling:false,reason:'No documented public API contract is configured. This helper opens the official interface; it does not submit indicator selections or download data.',coverage:'Aggregate patent, trademark, industrial-design, utility-model, PCT, Madrid, and Hague indicators. Availability and time coverage vary by indicator.',countingWarning:'WIPO documents different reporting types, missing-value rules, first-named-applicant origin, fractional technology counting, and revisions to Patstat-derived indicators. Record the indicator, filters, reporting type, download date, and source notes with every export.',docs:'https://www.wipo.int/en/web/ip-statistics/about',dataCatalog:'https://www.wipo.int/en/web/ip-statistics'};
 if(source==='google-patents'){
  if(publication){const id=publication.toUpperCase().replace(/[\s,-]/g,'');if(!/^[A-Z]{2}\d{4,15}[A-Z]\d?$/.test(id))throw new Error('Use a publication identifier with kind code, for example US11244675B2');return {source,mode:'publication-link',url:'https://patents.google.com/patent/'+id+'/en',publication:id,authority:'third-party-reproduction',retrieved:false,warning:'Read the original PDF; metadata, translations and legal-status annotations are distinct from the original patent.'};}
  return {source,mode:'hosted-search-link',url:'https://patents.google.com/?q='+encodeURIComponent(query),retrieved:false,exportLimit:'Google documents CSV export of up to the top 1000 results; this is not a complete CPC population.',help:'https://support.google.com/faqs/answer/7049588?hl=en'};
 }
 if(source==='google-bigquery'){
  const code=cpc.toUpperCase().replace(/\s/g,'');if(!/^[A-HY]\d{2}[A-Z](?:\d{1,4}\/\d{2,6})?$/.test(code))throw new Error('Supply a CPC subclass or full symbol');
  if(!Number.isInteger(from)||!Number.isInteger(to)||from<1970||to<from||to>new Date().getUTCFullYear()||to-from>30)throw new Error('Invalid year range');
  const subclass=/^[A-HY]\d{2}[A-Z]$/.test(code);
  const sql='SELECT DIV(publication_date,10000) AS year, COUNT(DISTINCT publication_number) AS publications\nFROM `patents-public-data.patents.publications`\nWHERE country_code = @country AND publication_date BETWEEN @start_date AND @end_date\nAND EXISTS (SELECT 1 FROM UNNEST(cpc) AS c WHERE '+(subclass?'STARTS_WITH(c.code,@cpc)':'c.code=@cpc')+')\nGROUP BY year ORDER BY year';
  const param=(name,type,value)=>({name,parameterType:{type},parameterValue:{value:String(value)}});
  return {source,mode:'query-plan-only',connected:false,projectRequired:true,consoleUrl:'https://console.cloud.google.com/bigquery',table:'patents-public-data.patents.publications',parameters:{country:'US',cpc:code,from,to},tableFreshness:'The table and referenced fields were live-validated on 2026-09-06. The capped report tool returns the provider table-modification timestamp for each run.',request:{configuration:{dryRun:true,query:{query:sql,useLegacySql:false,parameterMode:'NAMED',queryParameters:[param('country','STRING','US'),param('cpc','STRING',code),param('start_date','INT64',from*10000+101),param('end_date','INT64',to*10000+1231)]}}},countingUnit:'distinct US publication numbers by publication year',cpcMatch:subclass?'subclass prefix':'exact symbol',execution:'This function returns a plan and does not execute it. Use research_bigquery_estimate for a dry run or research_bigquery_cpc_report for the separately capped no-billing-sandbox query and report.',coverage:'Not application filing counts or patent-family counts; grants and application publications can represent the same invention. Recent unpublished applications are absent.',docs:'https://docs.cloud.google.com/bigquery/public-data'};
 }
 throw new Error('Unknown external provider');
};const j=$input.first().json;return [{json:externalAccess(j.body||j)}];
